const ajv = new Ajv04({ strict: false, allErrors: false })
const validate = ajv.compile(schema)

const dir = 'src/test/bamboo-spec'
let ok = 0,
  fail = 0
for (const f of fs.readdirSync(dir).sort()) {
  const p = path.join(dir, f)
  const raw = fs.readFileSync(p, 'utf8')
  const data = f.endsWith('.json') ? JSON.parse(raw) : YAML.parse(raw)
  const valid = validate(data)
  if (valid) {
    ok++
    console.log('PASS', f)
  } else {
    fail++
    console.log('FAIL', f)
    console.log('   ', JSON.stringify(validate.errors?.slice(0, 4)))
  }
}
// Also test synthetic docs covering full requirements
const extraDir = process.argv[2]
if (extraDir) {
  for (const f of fs.readdirSync(extraDir).sort()) {
