    const raw = fs.readFileSync(p, 'utf8')
    const data = f.endsWith('.json') ? JSON.parse(raw) : YAML.parse(raw)
    const valid = validate(data)
    if (valid) {
      ok++
      console.log('PASS(extra)', f)
    } else {
      fail++
      console.log('FAIL(extra)', f)
      console.log('   ', JSON.stringify(validate.errors?.slice(0, 6)))
    }
  }
}
